ve.prototype === prototype,\n        );\n        if (index === -1)\n          throw new TypeError(`invalid native ${name}`);\n        if (\n            !(name === 'Maybe' && index === 0) &&\n            !Object.hasOwn(value, 'value')\n        ) {\n          throw new TypeError(`missing native ${name} payload`);\n        }\n        fields =\n            name === 'Maybe' && index === 0 ? [] : [value.value];\n      } else {\n        if (\n            !(value instanceof ls.DataValue) ||\n            !tags.includes(value.tag)\n        ) {\n          throw new TypeError(`invalid constructor for ${name}`);\n        }\n        index = tags.indexOf(value.tag);\n        fields = value.fields;\n      }\n      const arity = name === 'Maybe' && index === 0 ? 0 : 1;\n      if (fields.length !== arity) {\n        throw new TypeError(`wrong constructor arity for ${name}`);\n      }\n      const converted =\n          arity === 0\n            ? []\n            : [\n                this.#walk(\n                    args[name === 'Maybe' ? 0 : index],\n                    fields[0],\n                    bits,\n                    mode,\n                    symbols,\n                ),\n              ];\n      return mode === 'native'\n        ? new classes[index](...converted)\n        : new ls.DataValue(tags[index], converted);\n    }\n    throw new TypeError(`unsupported type: ${name}`);\n  }\n\n  // Values in generated code are checked where they are built, decoded or\n  // drawn, so constructing checks only the new node and matching only\n  // dispatches; a deep check of each would make recursion quadratic.\n  construct(type, tag, fields, bits = 64, symbols = new Map()) {\n    if (type.name === 'List') return ls.construct(tag, fields);\n    this.#check(type);\n    return this.#walk(type, new ls.DataValue(tag, fields), bits, 'shallow', symbols);\n  }\n\n  match(type, value, branches, bits = 64, symbols = new Map()) {\n    const checked = value;\n    if (type.name === 'List')\n      return ls.matchList(checked, branches);\n    for (const [tag, branch] of branches) {\n      if (checked.tag === tag) return branch(...checked.fields);\n    }\n    throw new TypeError(`missing match branch: ${checked.tag}`);\n  }\n\n  equal(type, left, right, bits = 64, symbols = new Map()) {\n    left = this.validate(type, left, bits, symbols);\n    right = this.validate(type, right, bits, symbols);\n    const constructors = this.constructors(type);\n    if (constructors !== null) {\n      if (left.tag !== right.tag) return false;\n      const constructor = constructors.find(\n          (item) => item.tag === left.tag,\n      );\n      return constructor.fields.every((field, index) =>\n          this.equal(\n              field.type,\n              left.fields[index],\n              right.fields[index],\n              bits,\n              symbols,\n          ),\n      );\n    }\n    const {name, args} = type;\n    if (args.length === 0) return ls.equal(left, right, name, name);\n    if (name === 'List') {\n      return (\n        left.length === right.length &&\n          left.every((item, index) =>\n              this.equal(args[0], item, right[index], bits, symbols),\n          )\n      );\n    }\n    if (name === 'Nullable' || name === 'Optional') {\n      return (\n        left.present === right.present &&\n          (!left.present ||\n            this.equal(\n                args[0],\n                left.value,\n                right.value,\n                bits,\n                symbols,\n            ))\n      );\n    }\n    if (left.tag !== right.tag) return false;\n    if (left.fields.length === 0) return true;\n    const index = left.tag === 'Either::Right' ? 1 : 0;\n    return this.equal(\n        args[index],\n        left.fields[0],\n        right.fields[0],\n        bits,\n        symbols,\n    );\n  }\n}\n"
runtimeSource "web-data-strategies" = "// Native fast-check generation and shrinking for instantiated Core schemas.\nimport * as fc from 'fast-check';\nimport * as ls from './lawspec_runtime.mjs';\nimport {RefinementViolation, witnessed, witnessInstances} from './lawspec_schema.mjs';\n\n// fast-check has no empty arbitrary: an always-false filter would loop forever.\n// A native factory may ignore this argument, but drawing it must fail promptly.\nclass EmptyArgumentArbitrary extends fc.Arbitrary {\n  constructor(type, budget) {\n    super();\n    this.type = type;\n    this.budget = budget;\n  }\n\n  generate() {\n    throw new RangeError(\n        `no native generator argument for ${JSON.stringify(this.type)} ` +\n          `within node budget ${this.budget}`,\n    );\n  }\n\n  canShrinkWithoutContext() {\n    return false;\n  }\n\n  shrink() {\n    return fc.Stream.nil();\n  }\n}\n\n// Preserve the underlying Value and shrink context while bounding rejection.\nclass ContractArbitrary extends fc.Arbitrary {\n  constructor(source, accepts, attempts, name) {\n    super();\n    this.source = source;\n    this.accepts = accepts;\n    this.attempts = attempts;\n    this.name = name;\n  }\n\n  generate(random, bias) {\n    for (let attempt = 0; attempt < this.attempts; ++attempt) {\n      const value = this.source.generate(random, bias);\n      if (this.accepts(value.value)) return value;\n    }\n    throw new RangeError(\n        `constructor generation exhausted for ${this.name}`,\n    );\n  }\n\n  canShrinkWithoutContext(value) {\n    return (\n      this.source.canShrinkWithoutContext(value) && this.accepts(value)\n    );\n  }\n\n  shrink(value, context) {\n    return this.source\n        .shrink(value, context)\n        .filter((candidate) => this.accepts(candidate.value));\n  }\n}\n\nexport function strategy(\n    schema,\n    reference,\n    bits,\n    budget,\n    scalar,\n    symbols = new Map(),\n    witnesses = [],\n    maxAttempts = 1000,\n    nativeGenerators = new Map(),\n    nativeSchema = schema,\n    index = null,\n) {\n  if (!Number.isSafeInteger(budget) || budget < 1) {\n    throw new RangeError('structural node budget must be positive');\n  }\n  if (bits !== 32 && bits !== 64) {\n    throw new RangeError('machineBits must be 32 or 64');\n  }\n  schema.constructors(reference);\n  nativeGenerators = new Map(nativeGenerators);\n  for (const [name, factory] of nativeGenerators) {\n    if (typeof name !== 'string' || typeof factory !== 'function') {\n      throw new TypeError('invalid native generator binding');\n    }\n  }\n  if (!Number.isSafeInteger(maxAttempts) || maxAttempts < 1) {\n    throw new RangeError('constructor attempt budget must be positive');\n  }\n  const seeds = new Map();\n  function remember(type, value) {\n    const constructors = schema.constructors(type);\n    let children = [];\n    if (constructors !== null) {\n      const constructor = constructors.find(\n          (item) => item.tag === value.tag,\n      );\n      const types = witnessed(constructor, value.fields);\n      children = constructor.fields.map((field, index) => [\n        types[index],\n        value.fields[index],\n      ]);\n    } else if (type.name === 'List') {\n      children = value.map((child) => [type.args[0], child]);\n    } else if (\n        ['Nullable', 'Optional'].includes(type.name) &&\n        value.present\n    ) {\n      children = [[type.args[0], value.value]];\n    } else if (type.name === 'Maybe' && value.tag === 'Maybe::Just') {\n      children = [[type.args[0], value.fields[0]]];\n    } else if (type.name === 'Either') {\n      children = [\n        [type.args[value.tag === 'Either::Right' ? 1 : 0], value.fields[0]],\n      ];\n    }\n    const cost =\n        1 +\n        children.reduce(\n            (total, [childType, child]) => total + remember(childType, child),\n            0,\n        );\n    const key = JSON.stringify(type);\n    if (!seeds.has(key)) seeds.set(key, []);\n    seeds.get(key).push({cost, value});\n    return cost;\n  }\n  for (const value of witnesses) {\n    remember(reference, schema.validate(reference, value, bits, symbols));\n  }\n  function accepts(type, value) {\n    try {\n      schema.validate(type, value, bits, symbols);\n      return true;\n    } catch (error) {\n      if (error instanceof RefinementViolation) return false;\n      throw error;\n    }\n  }\n  const minima = new Map();\n  const inhabitants = new Map();\n  const arbitraries = new Map();\n  const key = (type, available) => JSON.stringify([type, available]);\n\n  function minimum(type, limit) {\n    const id = key(type, limit);\n    if (minima.has(id)) return minima.get(id);\n    let result = null;\n    for (let cost = 1; cost <= limit; ++cost) {\n      if (inhabited(type, cost)) {\n        result = cost;\n        break;\n      }\n    }\n    minima.set(id, result);\n    return result;\n  }\n\n  function allocation(fields, available) {\n    const costs = [];\n    for (const field of fields) {\n      const cost = minimum(field.type, available);\n      if (cost === null) return null;\n      costs.push(cost);\n      available -= cost;\n    }\n    return costs.map(\n        (cost, index) =>\n            cost +\n            Math.floor(available / costs.length) +\n            Number(index < available % costs.length),\n    );\n  }\n\n  function inhabited(type, available) {\n    if (available < 1) return false;\n    if (nativeGenerators.has(type.name)) return true;\n    const id = key(type, available);\n    if (inhabitants.has(id)) return inhabitants.get(id);\n    const constructors = schema.constructors(type);\n    let result;\n    if (constructors !== null) {\n      result = constructors.some((item) => witnessInstances(item).some(\n          ([fields]) => allocation(fields, available - 1) !== null,\n      ));\n    } else if (\n        type.args.length === 0 ||\n        ['List', 'Maybe', 'Nullable', 'Optional'].includes(type.name)\n    ) {\n      result = true;\n    } else if (type.name === 'Either') {\n      result = type.args.some((child) => inhabited(child, available - 1));\n    } else {\n      throw new TypeError(`unsupported generator type: ${type.name}`);\n    }\n    inhabitants.set(id, result);\n    return result;\n  }\n\n  function build(type, available) {\n    const id = key(type, available);\n    if (arbitraries.has(id)) return arbitraries.get(id);\n    if (nativeGenerators.has(type.name)) {\n      const children = type.args.map((child) => {\n        const remaining = Math.max(1, available - 1);\n        const source = inhabited(child, remaining)\n          ? build(child, remaining)\n          : new EmptyArgumentArbitrary(child, remaining);\n        return source.map((value) =>\n            nativeSchema.toNative(child, value, bits, symbols),\n        );\n      });\n      const source = nativeGenerators.get(type.name)(...children);\n      if (!(source instanceof fc.Arbitrary)) {\n        throw new TypeError(\n            `native generator ${type.name} must return an arbitrary`,\n        );\n      }\n      const result = source.map((value) => {\n        try {\n          return nativeSchema.fromNative(type, value, bits, symbols);\n        } catch (error) {\n          throw new TypeError(\n              `native generator ${type.name}: ${error.message}`,\n              {cause: error},\n          );\n        }\n      });\n      arbitraries.set(id, result);\n      return result;\n    }\n    if (!inhabited(type, available)) {\n      throw new RangeError(\n          `no value of ${type.name} within structural node budget ${available}`,\n      );\n    }\n    const constructors = schema.constructors(type);\n    let result;\n    if (constructors !== null) {\n      const alternatives = [];\n      for (const constructor of constructors) {\n        for (const [declared, keys] of witnessInstances(constructor)) {\n          const costs = allocation(declared, available - 1);\n          if (costs === null) continue;\n          const children = declared.map((field, index) =>\n              build(field.type, costs[index]),\n          );\n          const values = fc\n              .tuple(...children)\n              .map((fields) => new ls.DataValue(constructor.tag, [...fields, ...keys]));\n          alternatives.push(values);\n        }\n      }\n      result = fc.oneof({withCrossShrink: true}, ...alternatives);\n      if (CANONICAL[type.name]) result = result.map(CANONICAL[type.name]);\n    } else if (type.args.length === 0) {\n      result = scalar(type.name).map((value) =>\n          schema.validate(type, value, bits, symbols),\n      );\n    } else if (type.name === 'List') {\n      const remaining = available - 1;\n      const cost = minimum(type.args[0], remaining);\n      const max = cost === null ? 0 : Math.floor(remaining / cost);\n      result = fc.integer({min: 0, max}).chain((length) =>\n          length === 0\n            ? fc.constant([])\n            : fc.array(build(type.args[0], Math.floor(remaining / length)), {\n                minLength: length,\n                maxLength: length,\n              }),\n      );\n    } else if (['Maybe', 'Nullable', 'Optional'].includes(type.name)) {\n      const maybe = type.name === 'Maybe';\n      const absent = fc.constant(\n          maybe\n            ? new ls.DataValue('Maybe::Nothing', [])\n            : new ls.Presence(type.name, false),\n      );\n      result = inhabited(type.args[0], available - 1)\n        ? fc.oneof(\n            {withCrossShrink: true},\n            absent,\n            build(type.args[0], available - 1).map((value) =>\n                maybe\n                  ? new ls.DataValue('Maybe::Just', [value])\n                  : new ls.Presence(type.name, true, value),\n            ),\n          )\n        : absent;\n    } else if (type.name === 'Either') {\n      const tags = ['Either::Left', 'Either::Right'];\n      result = fc.oneof(\n          {withCrossShrink: true},\n          ...type.args.flatMap((child, index) =>\n              inhabited(child, available - 1)\n                ? [\n                    build(child, available - 1).map(\n                        (value) => new ls.DataValue(tags[index], [value]),\n                    ),\n                  ]\n                : [],\n          ),\n      );\n    } else {\n      throw new TypeError(`unsupported generator type: ${type.name}`);\n    }\n    const values = (seeds.get(JSON.stringify(type)) ?? [])\n        .filter((item) => item.cost <= available)\n        .map((item) => item.value);\n    if (values.length) {\n      result = fc.oneof(\n          {withCrossShrink: true},\n          result,\n          fc.constantFrom(...values),\n      );\n    }\n    arbitraries.set(id, result);\n    return result;\n  }\n\n  // Reject complete candidates, not subtrees: an impossible child must not\n  // prevent choosing a viable sibling constructor on the next attempt.\n  const root =\n      index === null\n        ? build(reference, budget)\n        : indexedArbitrary(\n            schema,\n            reference,\n            Number(index[0]),\n            index[1],\n            budget,\n            build,\n            inhabited,\n            (type, value) => accepts(type, value),\n          );\n  return new ContractArbitrary(\n      root,\n      (value) => accepts(reference, value),\n      maxAttempts,\n      reference.name,\n  );\n}\n\n// Sorted items without repeated keys: a Set's or a KeyVal's invariant.\nfunction canonical(key) {\n  return (value) => {\n    const items = [...value.fields[0]].sort((a, b) => ls.compareValues(key(a), key(b)));\n    const distinct = items.filter((item, index) =>\n      index === 0 || ls.compareValues(key(items[index - 1]), key(item)) !== 0);\n    return new ls.DataValue(value.tag, [distinct]);\n  };\n}\n\n// Generated collections are canonicalised rather than filtered.\nconst CANONICAL = {\n  'lawspec.collections::type::Set': canonical((item) => item),\n  'lawspec.collections::type::KeyVal': canonical((entry) => entry.fields[0]),\n};\n\nconst INDEX_SLACK = 16;\nconst INDEX_CHOICES = 6;\nconst INDEX_OPERATORS = ['+', '-', '*', 'div', 'mod', '^'];\n\n// A prefix index term over field indices (f<i>), literals (c<n>) and the\n// natural operators. Returns the term and the position after it.\nfunction parseIndexTerm(tokens, at) {\n  const token = tokens[at];\n  if (token === undefined) throw new TypeError('malformed index term');\n  if (token[0] === 'c') return [['c', Number(token.slice(1))], at + 1];\n  if (token[0] === 'f') return [['f', Number(token.slice(1))], at + 1];\n  if (INDEX_OPERATORS.includes(token)) {\n    const [left, afterLeft] = parseIndexTerm(tokens, at + 1);\n    const [right, afterRight] = parseIndexTerm(tokens, afterLeft);\n    return [[token, left, right], afterRight];\n  }\n  throw new TypeError('malformed index term');\n}\n\n// Natural index arithmetic; null when an operation has no natural value.\nfunction evalIndexTerm(term, fields) {\n  if (term[0] === 'c') return term[1];\n  if (term[0] === 'f') return fields.has(term[1]) ? fields.get(term[1]) : null;\n  const x = evalIndexTerm(term[1], fields);\n  const y = evalIndexTerm(term[2], fields);\n  if (x === null || y === null) return null;\n  let result;\n  switch (term[0]) {\n    case '+': result = x + y; break;\n    case '-': result = x >= y ? x - y : null; break;\n    case '*': result = x * y; break;\n    case 'div': result = y > 0 ? Math.floor(x / y) : null; break;\n    case 'mod': result = y > 0 ? x % y : null; break;\n    default: result = y <= 64 ? x ** y : null;\n  }\n  return result !== null && Number.isSafeInteger(result) ? result : null;\n}\n\nfunction indexTermFields(term) {\n  if (term[0] === 'c') return [];\n  if (term[0] === 'f') return [term[1]];\n  return [...indexTermFields(term[1]), ...indexTermFields(term[2])];\n}\n\n// Construct values whose structural index equals target. Each constructor\n// carries its index term then its guards, in prefix notation over field\n// indices. Reachability is a forward fixpoint over levels 0..target+slack, so\n// a child may exceed its parent's index; the target is then solved backwards,\n// and nothing is filtered away.\nfunction indexedArbitrary(\n    schema,\n    reference,\n    target,\n    equations,\n    budget,\n    build,\n    inhabited,\n    accepts,\n) {\n  if (!Number.isSafeInteger(target)) {\n    throw new RangeError('index target must be an integer');\n  }\n  if (schema.constructors(reference) === null) {\n    throw new TypeError('indexed generation requires a data type');\n  }\n  const limit = Math.max(target, 0) + INDEX_SLACK;\n  const key = (...parts) => JSON.stringify(parts);\n  const parsed = new Map();\n  const equation = (constructor) => {\n    if (parsed.has(constructor.tag)) return parsed.get(constructor.tag);\n    const texts = equations[constructor.tag];\n    if (texts === undefined) {\n      throw new TypeError(`missing index equation for ${constructor.tag}`);\n    }\n    const tokens = texts[0].split(' ');\n    const [term, end] = parseIndexTerm(tokens, 0);\n    if (end !== tokens.length) throw new TypeError('malformed index term');\n    const guards = texts.slice(1).map((text) => {\n      const parts = text.split(' ');\n      if (parts[0] !== '==' && parts[0] !== '>=') {\n        throw new TypeError('malformed index guard');\n      }\n      const [left, afterLeft] = parseIndexTerm(parts, 1);\n      const [right] = parseIndexTerm(parts, afterLeft);\n      return [parts[0], left, right];\n    });\n    const positions = [...new Set([\n      ...indexTermFields(term),\n      ...guards.flatMap(([, left, right]) => [\n        ...indexTermFields(left), ...indexTermFields(right)]),\n    ])];\n    const result = {term, guards, positions};\n    parsed.set(constructor.tag, result);\n    return result;\n  };\n  const plainFields = (constructor, positions) =>\n      constructor.fields.every(\n          (field, index) =>\n              positions.includes(index) || inhabited(field.type, budget),\n      );\n  const families = [];\n  const familyKeys = new Set();\n  const pending = [reference];\n  while (pending.length) {\n    const type = pending.pop();\n    if (familyKeys.has(key(type))) continue;\n    if (schema.constructors(type) === null) {\n      throw new TypeError('indexed generation requires a data type');\n    }\n    familyKeys.add(key(type));\n    families.push(type);\n    for (const constructor of schema.constructors(type)) {\n      for (const position of equation(constructor).positions) {\n        pending.push(constructor.fields[position].type);\n      }\n    }\n  }\n  const holds = ([relation, left, right], fields) => {\n    const x = evalIndexTerm(left, fields);\n    const y = evalIndexTerm(right, fields);\n    if (x === null || y === null) return false;\n    return relation === '==' ? x === y : x >= y;\n  };\n  // Every assignment of reachable indices to the index fields that satisfies\n  // the guards, with the index it produces.\n  function assignments(constructor, reach) {\n    const {term, guards, positions} = equation(constructor);\n    const choices = positions.map((position) => {\n      const values = [];\n      for (let value = 0; value <= limit; ++value) {\n        if (reach.has(key(constructor.fields[position].type, value))) {\n          values.push([position, value]);\n        }\n      }\n      return values;\n    });\n    const found = [];\n    const extend = (at, current) => {\n      if (at === choices.length) {\n        const fields = new Map(current);\n        if (guards.every((guard) => holds(guard, fields))) {\n          const value = evalIndexTerm(term, fields);\n          if (value !== null && value <= limit) found.push([value, current]);\n        }\n        return;\n      }\n      for (const choice of choices[at]) extend(at + 1, [...current, choice]);\n    };\n    extend(0, []);\n    return found;\n  }\n  let reach = new Set();\n  for (;;) {\n    const grown = new Set(reach);\n    for (const type of families) {\n      for (const constructor of schema.constructors(type)) {\n        if (!plainFields(constructor, equation(constructor).positions)) {\n          continue;\n        }\n        for (const [value] of assignments(constructor, reach)) {\n          grown.add(key(type, value));\n        }\n      }\n    }\n    if (grown.size === reach.size) break;\n    reach = grown;\n  }\n  const solutions = new Map();\n  const solve = (constructor, k) => {\n    const id = key(constructor.tag, k);\n    if (!solutions.has(id)) {\n      solutions.set(id, assignments(constructor, reach)\n          .filter(([value]) => value === k)\n          .map(([, assignment]) => assignment));\n    }\n    return solutions.get(id);\n  };\n  const arbitraries = new Map();\n  function indexed(type, k) {\n    const id = key(type, k);\n    if (arbitraries.has(id)) return arbitraries.get(id);\n    const alternatives = [];\n    for (const constructor of schema.constructors(type)) {\n      if (!plainFields(constructor, equation(constructor).positions)) continue;\n      const choices = solve(constructor, k);\n      if (!choices.length) continue;\n      const assemble = (assignment) => {\n        const targets = new Map(assignment);\n        return fc\n            .tuple(\n            ...constructor.fields.map((field, index) =>\n                targets.has(index)\n                  ? indexed(field.type, targets.get(index))\n                  : build(field.type, budget),\n            ),\n          )\n            .map((fields) => new ls.DataValue(constructor.tag, fields));\n      };\n      let values = fc.constantFrom(...choices).chain(assemble);\n      if (constructor.predicates && constructor.predicates.length) {\n        values = values.filter((value) => accepts(type, value));\n      }\n      alternatives.push(values);\n    }\n    if (!alternatives.length) {\n      throw new RangeError(`no value of ${type.name} has index ${k}`);\n    }\n    const result =\n        alternatives.length === 1\n          ? alternatives[0]\n          : fc.oneof({withCrossShrink: true}, ...alternatives);\n    arbitraries.set(id, result);\n    return result;\n  }\n  if (!reach.has(key(reference, target))) {\n    // An open target (negative), or one drawn from earlier inputs that breaks\n    // their preconditions or names no value, generates from the smallest\n    // reachable indices; an index claim rejects a mismatch.\n    const levels = [];\n    for (let level = 0; level <= limit && levels.length < INDEX_CHOICES; ++level) {\n      if (reach.has(key(reference, level))) levels.push(level);\n    }\n    if (!levels.length) {\n      throw new RangeError(`no value of ${reference.name} has an index`);\n    }\n    return fc.constantFrom(...levels).chain((level) => indexed(reference, level));\n  }\n  return indexed(reference, target);\n}\n"
runtimeSource "java" = "package lawspec.runtime;\n\nimport java.math.BigDecimal;\nimport java.math.BigInteger;\nimport java.math.RoundingMode;\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Objects;\nimport java.util.Random;\nimport java.util.function.BiFunction;\nimport java.util.function.Function;\nimport java.util.function.Supplier;\n\n/** Portable scalar and collection values, independent of test frameworks. */\npublic final class LawSpecRuntime {\n  private LawSpecRuntime() {}\n\n  public record Value(String type, Object data) {\n    @Override\n    public String toString() {\n      return \"Value[type=\"\n          + type\n          + \", data=\"\n          + (data instanceof int[] units ? Arrays.toString(units) : String.valueOf(data))\n          + \"]\";\n    }\n  }\n\n  public record Complex(double real, double imaginary) {}\n\n  public record SymbolValue(String description) {}\n\n  public record Presence(boolean present, Value value) {}\n\n  public sealed interface Maybe<T> permits Nothing, Just {}\n\n  public record Nothing<T>() implements Maybe<T> {}\n\n  public record Just<T>(T value) implements Maybe<T> {}\n\n  public sealed interface Either<L, R> permits Left, Right {}\n\n  public record Left<L, R>(L value) implements Either<L, R> {}\n\n  public record Right<L, R>(R value) implements Either<L, R> {}\n\n  public record Data(String tag, List<Value> fields) {\n    public Data {\n      fields = List.copyOf(fields);\n    }\n  }\n\n  public record Ratio(BigInteger n, BigInteger d) {\n    public Ratio {\n      if (d.signum() == 0) throw new ArithmeticException(\"exact division by zero\");\n      if (d.signum() < 0) {\n        n = n.negate();\n        d = d.negate();\n      }\n      var gcd = n.gcd(d);\n      n = n.divide(gcd);\n      d = d.divide(gcd);\n    }\n  }\n\n  private static final java.util.regex.Pattern INTEGER_TYPE =\n      java.util.regex.Pattern.compile(\"(U?Int(8|16|32|64|Size)|UIntPtr|BigU?Int|Integer)\");\n\n  public static boolean integerType(String t) {\n    return INTEGER_TYPE.matcher(t).matches();\n  }\n\n  public static boolean exactType(String t) {\n    return integerType(t) || t.equals(\"Decimal\") || t.equals(\"Rational\");\n  }\n\n  public static Value integer(String t, String n) {\n    return new Value(t, new BigInteger(n));\n  }\n\n  public static Value decimal(String c, String e) {\n    return new Value(\n        \"Decimal\", new BigDecimal(new BigInteger(c), Math.negateExact(Integer.parseInt(e))));\n  }\n\n  public static Value rational(String n, String d) {\n    return new Value(\"Rational\", new Ratio(new BigInteger(n), new BigInteger(d)));\n  }\n\n  public static Value bool(boolean b) {\n    return new Value(\"Bool\", b);\n  }\n\n  public static Value floating(String t, String bits) {\n    return new Value(\n        t,\n        t.equals(\"Float32\")\n            ? (double) Float.intBitsToFloat(Integer.parseUnsignedInt(bits, 16))\n            : Double.longBitsToDouble(Long.parseUnsignedLong(bits, 16)));\n  }\n\n  public static Value complex(String t, Value r, Value i) {\n    return new Value(t, new Complex((double) r.data, (double) i.data));\n  }\n\n  public static Value sequence(String t, int[] units) {\n    return new Value(t, Arrays.stream(units).boxed().toList());\n  }\n\n  public static Value character(String t, int c) {\n    return new Value(t, c);\n  }\n\n  public static Value absent(String t) {\n    return new Value(t, null);\n  }\n\n  public static Value present(String t, Value v) {\n    return new Value(t, new Presence(v != null, v));\n  }\n\n  public static Value symbol(String id, String description, Map<String, Object> symbols) {\n    return new Value(\"Symbol\", symbols.computeIfAbsent(id, k -> new SymbolValue(description)));\n  }\n\n  public static Value list(String type, List<Value> values) {\n    if (!type.startsWith(\"List \")) {\n      throw new IllegalArgumentException(\"List type required\");\n    }\n    return new Value(type, List.copyOf(values));\n  }\n\n  private static List<Value> listElements(Value value) {\n    if (value == null\n        || !value.type.startsWith(\"List \")\n        || !(value.data instanceof List<?> values)) {\n      throw new IllegalArgumentException(\"List value required\");\n    }\n    var result = new ArrayList<Value>(values.size());\n    for (Object element : values) {\n      if (!(element instanceof Value field)) {\n        throw new IllegalArgumentException(\"invalid List element representation\");\n      }\n      result.add(field);\n    }\n    return result;\n  }\n\n  public static Value construct(String type, String tag, Value[] fields) {\n    if (sumType(type)) {\n      if (sumFields(type, tag).size() != fields.length) {\n        throw new IllegalArgumentException(\"invalid constructor arity: \" + tag);\n      }\n      return new Value(type, new Data(tag, Arrays.asList(fields)));\n    }\n    if (tag.equals(\"List::Nil\") && fields.length == 0) {\n      return list(type, List.of());\n    }\n    if (tag.equals(\"List::Cons\") && fields.length == 2) {\n      var values = new ArrayList<Value>();\n      values.add(fields[0]);\n      values.addAll(listElements(fields[1]));\n      return list(type, values);\n    }\n    throw new IllegalArgumentException(\"invalid constructor or arity: \" + tag);\n  }\n\n  private static boolean sumType(String type) {\n    return type.startsWith(\"Maybe \") || type.startsWith(\"Either \");\n  }\n\n  private static List<String> eitherArguments(String type) {\n    if (!type.startsWith(\"Either \")) {\n      throw new IllegalArgumentException(\"Either type required\");\n    }\n    var arguments = new ArrayList<String>();\n    int cursor = 7;\n    while (cursor < type.length()) {\n      if (type.charAt(cursor) != '(') {\n        throw new IllegalArgumentException(\"invalid Either type: \" + type);\n      }\n      int start = ++cursor;\n      int depth = 1;\n      while (cursor < type.length() && depth > 0) {\n        char unit = type.charAt(cursor++);\n        if (unit == '(') depth++;\n        if (unit == ')') depth--;\n      }\n      if (depth != 0 || cursor == start + 1) {\n        throw new IllegalArgumentException(\"invalid Either type: \" + type);\n      }\n      arguments.add(type.substring(start, cursor - 1));\n      if (cursor < type.length() && type.charAt(cursor++) != ' ') {\n        throw new IllegalArgumentException(\"invalid Either type: \" + type);\n      }\n    }\n    if (arguments.size() != 2) {\n      throw new IllegalArgumentException(\"Either requires two type arguments\");\n    }\n    return arguments;\n  }\n\n  private static List<String> sumFields(String type, String tag) {\n    if (type.startsWith(\"Maybe \")) {\n      if (tag.equals(\"Maybe::Nothing\")) return List.of();\n      if (tag.equals(\"Maybe::Just\")) return List.of(type.substring(6));\n    } else if (type.startsWith(\"Either \")) {\n      var arguments = eitherArguments(type);\n      if (tag.equals(\"Either::Left\")) return List.of(arguments.get(0));\n      if (tag.equals(\"Either::Right\")) return List.of(arguments.get(1));\n    }\n    throw new IllegalArgumentException(\"invalid constructor \" + tag + \" for \" + type);\n  }\n\n  private static Data dataValue(Value value) {\n    if (value == null\n        || !(value.data instanceof Data data)\n        || sumFields(value.type, data.tag).size() != data.fields.size()) {\n      throw new IllegalArgumentException(\"invalid sum value representation\");\n    }\n    return data;\n  }\n\n  public static <T> Maybe<T> maybeToNative(\n      String type, Value value, int bits, Function<Value, T> element) {\n    if (!type.startsWith(\"Maybe \")) throw new IllegalArgumentException(\"Maybe type required\");\n    var data = dataValue(convert(type, value, bits));\n    return data.tag.equals(\"Maybe::Nothing\")\n        ? new Nothing<>()\n        : new Just<>(element.apply(data.fields.getFirst()));\n  }\n\n  public static <L, R> Either<L, R> eitherToNative(\n      String type, Value value, int bits, Function<Value, L> left, Function<Value, R> right) {\n    if (!type.startsWith(\"Either \")) throw new IllegalArgumentException(\"Either type required\");\n    var data = dataValue(convert(type, value, bits));\n    return data.tag.equals(\"Either::Left\")\n        ? new Left<>(left.apply(data.fields.getFirst()))\n        : new Right<>(right.apply(data.fields.getFirst()));\n  }\n\n  public static Value matchMaybe(\n      Value value, Supplier<Value> nothing, Function<Value, Value> just) {\n    var data = dataValue(value);\n    return switch (data.tag) {\n      case \"Maybe::Nothing\" -> nothing.get();\n      case \"Maybe::Just\" -> just.apply(data.fields.getFirst());\n      default -> throw new IllegalArgumentException(\"Maybe value required\");\n    };\n  }\n\n  public static Value matchEither(\n      Value value, Function<Value, Value> left, Function<Value, Value> right) {\n    var data = dataValue(value);\n    return switch (data.tag) {\n      case \"Either::Left\" -> left.apply(data.fields.getFirst());\n      case \"Either::Right\" -> right.apply(data.fields.getFirst());\n      default -> throw new IllegalArgumentException(\"Either value required\");\n    };\n  }\n\n  public static <T> List<T> listToNative(\n      String type, Value value, int bits, Function<Value, T> element) {\n    var values = listElements(convert(type, value, bits));\n    var result = new ArrayList<T>(values.size());\n    for (Value field : values) {\n      result.add(element.apply(field));\n    }\n    return result;\n  }\n\n  public static Value refineElements(\n      Value value, Function<Value, Value> prepare, Function<Value, Value> predicate) {\n    var accepted = new ArrayList<Value>();\n    for (Value item : listElements(value)) {\n      Value prepared = prepare.apply(item);\n      if (truth(predicate.apply(prepared))) accepted.add(prepared);\n    }\n    return list(value.type, accepted);\n  }\n\n  public static Value allElements(Value value, Function<Value, Value> predicate) {\n    var values = listElements(value);\n    for (int index = 0; index < values.size(); index++) {\n      try {\n        if (!truth(predicate.apply(values.get(index)))) return bool(false);\n      } catch (RuntimeException error) {\n        throw new IllegalArgumentException(\n            \"List element \" + index + \": \" + error.getMessage(), error);\n      }\n    }\n    return bool(true);\n  }\n\n  public static Value matchList(\n      Value value, Supplier<Value> nil, BiFunction<Value, Value, Value> cons) {\n    var values = listElements(value);\n    if (values.isEmpty()) return nil.get();\n    return cons.apply(values.getFirst(), list(value.type, values.subList(1, values.size())));\n  }\n\n  private static Ratio ratio(Value v) {\n    if (integerType(v.type)) return new Ratio((BigInteger) v.data, BigInteger.ONE);\n    if (v.data instanceof Ratio r) return r;\n    if (v.data instanceof BigDecimal d) {\n      int s = d.scale();\n      return new Ratio(\n          s < 0 ? d.unscaledValue().multiply(BigInteger.TEN.pow(-s)) : d.unscaledValue(),\n          s < 0 ? BigInteger.ONE : BigInteger.TEN.pow(s));\n    }\n    throw new IllegalArgumentException(\"exact numeric value required\");\n  }\n\n  private static double real(Value v) {\n    if (v.data instanceof Double d) return d;\n    Ratio r = ratio(v);\n    return new BigDecimal(r.n)\n        .divide(new BigDecimal(r.d), new java.math.MathContext(400, RoundingMode.HALF_EVEN))\n        .doubleValue();\n  }\n\n  private static double precision(String t, double d) {\n    return t.equals(\"Float32\") || t.equals(\"Complex64\") ? (double) (float) d : d;\n  }\n\n  public static Value convert(String t, Value v, int bits) {\n    if (sumType(t)) {\n      var data = dataValue(v);\n      var types = sumFields(t, data.tag);\n      var fields = new ArrayList<Value>();\n      for (int i = 0; i < types.size(); i++) {\n        fields.add(convert(types.get(i), data.fields.get(i), bits));\n      }\n      return new Value(t, new Data(data.tag, fields));\n    }\n    if (t.startsWith(\"List \")) {\n      var result = new ArrayList<Value>();\n      for (Value field : listElements(v)) {\n        result.add(convert(t.substring(5), field, bits));\n      }\n      return list(t, result);\n    }\n    if (t.startsWith(\"Nullable \") || t.startsWith(\"Optional \")) {\n      int i = t.indexOf(' ');\n      String k = t.substring(0, i);\n      if (v.type.equals(k.equals(\"Nullable\") ? \"Null\" : \"Undefined\"))\n        return new Value(t, new Presence(false, null));\n      if (v.data instanceof Presence p)\n        return new Value(\n            t,\n            new Presence(p.present, p.present ? convert(t.substring(i + 1), p.value, bits) : null));\n      throw new IllegalArgumentException(\"tagged presence required\");\n    }\n    if (integerType(t)) {\n      Ratio r =\n          v.data instanceof Double d ? ratio(new Value(\"Decimal\", new BigDecimal(d))) : ratio(v);\n      if (!r.d.equals(BigInteger.ONE))\n        throw new ArithmeticException(\"fractional conversion to \" + t);\n      if (!t.equals(\"BigInt\") && !t.equals(\"Integer\")) {\n        if (t.startsWith(\"U\") || t.equals(\"BigUInt\")) {\n          if (r.n.signum() < 0) throw new ArithmeticException(\"integer outside \" + t + \" range\");\n        }\n        if (!t.equals(\"BigUInt\")) {\n          int w =\n              t.endsWith(\"Size\") || t.equals(\"UIntPtr\")\n                  ? bits\n                  : Integer.parseInt(t.replaceAll(\"\\\\D\", \"\"));\n          boolean signed = t.startsWith(\"Int\");\n          BigInteger hi = BigInteger.ONE.shiftLeft(signed ? w - 1 : w).subtract(BigInteger.ONE),\n              lo = signed ? BigInteger.ONE.shiftLeft(w - 1).negate() : BigInteger.ZERO;\n          if (r.n.compareTo(lo) < 0 || r.n.compareTo(hi) > 0)\n            throw new ArithmeticException(\"integer outside \" + t + \" range\");\n        }\n      }\n      return new Value(t, r.n);\n    }\n    if (t.equals(\"Rational\") || t.equals(\"Decimal\")) {\n      Ratio r =\n          v.data instanceof Double d ? ratio(new Value(\"Decimal\", new BigDecimal(d))) : ratio(v);\n      return new Value(\n          t, t.equals(\"Rational\") ? r : new BigDecimal(r.n).divide(new BigDecimal(r.d)));\n    }\n    if (t.startsWith(\"Float\"))\n      return new Value(\n          t, exactType(v.type) ? exactFloat(ratio(v), t.equals(\"Float32\")) : precision(t, real(v)));\n    if (t.startsWith(\"Complex\")) {\n      Complex c =\n          v.data instanceof Complex z\n              ? z\n              : new Complex(\n                  (double) convert(t.equals(\"Complex64\") ? \"Float32\" : \"Float64\", v, bits).data, 0);\n      return new Value(t, new Complex(precision(t, c.real), precision(t, c.imaginary)));\n    }\n    if (!t.equals(v.type))\n      throw new IllegalArgumentException(\"cannot convert \" + v.type + \" to \" + t);\n    return validate(t, v, bits);\n  }\n\n  private static boolean validUnit(String t, int c) {\n    return c >= 0\n        && c\n            <= (t.equals(\"Bytes\")\n                ? 255\n                : t.equals(\"Utf16Text\") || t.equals(\"CodeUnit16\") ? 65535 : 1114111)\n        && (!(t.equals(\"Char\") || t.equals(\"Text\")) || c < 55296 || c > 57343);\n  }\n\n  public static Value validate(String t, Value v, int bits) {\n    if (v == null && t.equals(\"Unit\")) return absent(\"Unit\");\n    if (v == null || !v.type.equals(t))\n      throw new IllegalArgumentException(\"invalid \" + t + \" representation\");\n    if (sumType(t)) {\n      var data = dataValue(v);\n      var types = sumFields(t, data.tag);\n      var fields = new ArrayList<Value>();\n      for (int i = 0; i < types.size(); i++) {\n        fields.add(validate(types.get(i), data.fields.get(i), bits));\n      }\n      return new Value(t, new Data(data.tag, fields));\n    }\n    if (t.startsWith(\"List \")) {\n      var result = new ArrayList<Value>();\n      for (Value field : listElements(v)) {\n        result.add(validate(t.substring(5), field, bits));\n      }\n      return list(t, result);\n    }\n    if (integerType(t)) return convert(t, v, bits);\n    Object data = v.data;\n    boolean valid;\n    if (t.startsWith(\"Nullable \") || t.startsWith(\"Optional \")) {\n      valid = data instanceof Presence;\n      if (valid) {\n        Presence p = (Presence) data;\n        if (p.present) validate(t.substring(t.indexOf(' ') + 1), p.value, bits);\n      }\n    } else if (List.of(\"Text\", \"CodePointText\", \"Utf16Text\", \"Bytes\").contains(t)) {\n      valid = data instanceof List<?>;\n      if (valid)\n        for (Object x : (List<?>) data)\n          if (!(x instanceof Integer c) || !validUnit(t, c)) valid = false;\n    } else if (List.of(\"Char\", \"CodePoint\", \"CodeUnit16\").contains(t))\n      valid = data instanceof Integer c && validUnit(t, c);\n    else if (t.equals(\"Bool\")) valid = data instanceof Boolean;\n    else if (t.equals(\"Decimal\")) valid = data instanceof BigDecimal;\n    else if (t.equals(\"Rational\")) valid = data instanceof Ratio;\n    else if (t.startsWith(\"Float\"))\n      valid =\n          data instanceof Double d\n              && (t.equals(\"Float64\") || Double.isNaN(d) || (double) (float) d.doubleValue() == d);\n    else if (t.startsWith(\"Complex\")) {\n      valid = data instanceof Complex;\n      if (valid) {\n        Complex c = (Complex) data;\n        String component = t.equals(\"Complex64\") ? \"Float32\" : \"Float64\";\n        validate(component, new Value(component, c.real), bits);\n        validate(component, new Value(component, c.imaginary), bits);\n      }\n    } else if (t.equals(\"Symbol\")) valid = data instanceof SymbolValue;\n    else valid = List.of(\"Unit\", \"Null\", \"Undefined\").contains(t) && data == null;\n    if (!valid) throw new IllegalArgumentException(\"invalid \" + t + \" representation\");\n    if (data instanceof List<?> xs) return new Value(t